def lis_length_dp(nums):
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # dp[i] = length of LIS ending at index i

    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
```

